import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { vi, describe, it, expect, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

const mockItems = [
  { id: '1', name: 'Widget', price: 29.99 },
  { id: '2', name: 'Gadget', price: 49.99 }
];

const renderCheckout = (cartItems = mockItems, paymentMock = vi.fn()) => {
  const onComplete = vi.fn();
  const onCancel = vi.fn();

  return {
    ...render(
      <CartProvider initialItems={cartItems}>
        <PaymentProvider processPayment={paymentMock}>
          <Checkout onComplete={onComplete} onCancel={onCancel} />
        </PaymentProvider>
      </CartProvider>
    ),
    onComplete,
    onCancel,
    paymentMock
  };
};

describe('Checkout - Happy Path', () => {
  it('completes full checkout flow successfully', async () => {
    const user = userEvent.setup();
    const { onComplete, paymentMock } = renderCheckout();
    paymentMock.mockResolvedValue({ orderId: 'ORD-12345' });

    // Arrange & Act: Shipping
    await user.type(screen.getByLabelText(/street address/i), '123 Main St');
    await user.type(screen.getByLabelText(/city/i), 'Austin');
    await user.selectOptions(screen.getByLabelText(/state/i), 'TX');
    await user.type(screen.getByLabelText(/zip/i), '78701');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Act: Payment
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'John Doe');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Act: Review & Place Order
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Assert
    await waitFor(() => {
      expect(screen.getByRole('status')).toHaveTextContent('ORD-12345');
    });
    expect(onComplete).toHaveBeenCalledWith('ORD-12345');
  });
});

describe('Checkout - Validation', () => {
  it('displays error for invalid ZIP code', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.type(screen.getByLabelText(/zip/i), 'invalid');
    await user.click(screen.getByRole('button', { name: /continue/i }));

    expect(screen.getByRole('alert')).toHaveTextContent(/valid zip/i);
    expect(screen.getByLabelText(/zip/i)).toHaveAttribute('aria-invalid', 'true');
  });
});

describe('Checkout - Edge Cases', () => {
  it('shows empty cart message when no items', async () => {
    const { onCancel } = renderCheckout([]);

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    await userEvent.click(screen.getByRole('button', { name: /continue shopping/i }));
    expect(onCancel).toHaveBeenCalled();
  });

  it('handles payment failure with retry option', async () => {
    const user = userEvent.setup();
    const { paymentMock } = renderCheckout();
    paymentMock.mockRejectedValueOnce(new Error('Card declined'));

    // Navigate to review step...
    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
    });
    expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
  });
});

describe('Checkout - Accessibility', () => {
  it('maintains focus management through steps', async () => {
    renderCheckout();
    expect(screen.getByRole('form', { name: /shipping/i })).toBeInTheDocument();
    expect(screen.getByLabelText(/street/i)).toHaveAccessibleName();
  });
});
